		return
	res = []
	for row in range((n + 1) // 2):
		rev_row = n - row
		cell_cnt = m if rev_row != row + 1 else (m + 1) // 2
		for i in range(cell_cnt):
			res.append(f'{row + 1} {i + 1}')
			if not (row + 1 == rev_row and i + 1 == m - i):
				res.append(f'{rev_row} {m - i}')
	print('\n'.join(res))
